let comparisonIds = [];
const comparisonKey = 'happiness-plaza-unit-comparison';
try {
  const saved = JSON.parse(localStorage.getItem(comparisonKey) || '[]');
  if (Array.isArray(saved)) comparisonIds = [...new Set(saved.filter(id=>byId.has(id)))].slice(0,3);
} catch {}
function updateComparison() {
  document.querySelectorAll('.compare-count').forEach(el => el.textContent = comparisonIds.length.toLocaleString('ar-EG'));
  try {localStorage.setItem(comparisonKey, JSON.stringify(comparisonIds));} catch {}
  document.querySelectorAll('[data-compare-unit]').forEach(button=>{
    const on=comparisonIds.includes(button.dataset.compareUnit);
    button.disabled = !on && comparisonIds.length >= 3;
    button.setAttribute('aria-pressed',String(on));
    button.textContent=on?'إزالة من المقارنة':button.disabled?'اكتمل اختيار ٣ وحدات':'أضف للمقارنة';
  });
}
function makeCompareButton(u) {
  const button = btn('', ()=>{
    const selected=comparisonIds.includes(u.id);
    if (selected) comparisonIds=comparisonIds.filter(id=>id!==u.id);
    else if (comparisonIds.length<3) comparisonIds.push(u.id);
    updateComparison();
  },'secondary');
  button.dataset.compareUnit=u.id;
  const on=comparisonIds.includes(u.id);
  button.disabled=!on && comparisonIds.length>=3;
  button.setAttribute('aria-pressed',String(on));
  button.textContent=on?'إزالة من المقارنة':button.disabled?'اكتمل اختيار ٣ وحدات':'أضف للمقارنة';
  return button;
}
