  const rows=[['الدور',u=>FLOORS[u.f]],['النشاط',u=>u.cat],['مساحة التأجير',u=>fmt(u.area)],['المساحة الإضافية',u=>u.extra?u.elab+' · '+fmt(u.extra):'غير مبيّنة'],['التوافر',u=>u.status]];
  const tb=table.createTBody();
