let activeChapter=-1;
const presentationBar=document.querySelector('#presentbar');
function closePresentation(){
  activeChapter=-1; presentationBar.hidden=true;
  document.body.classList.remove('meeting-on');document.querySelector('#meeting-start').setAttribute('aria-pressed','false');
}
function showChapter(index){
  activeChapter=index; presentationBar.hidden=false;
  document.body.classList.add('meeting-on'); document.querySelector('#meeting-start').setAttribute('aria-pressed','true');
  document.querySelector('#pres-title').textContent=(index+1).toLocaleString('ar-EG')+' / '+chapterStops.length.toLocaleString('ar-EG')+' · '+chapterStops[index][1];
  document.querySelector('#pres-prev').disabled=index===0;
  document.querySelector('#pres-next').disabled=index===chapterStops.length-1;
  const dest=chapterStops[index][0];
  for(const player of document.querySelectorAll("video")) if(!player.paused) player.pause();
  navigateSite(dest);
}
document.querySelector('#meeting-start').addEventListener('click',()=>{
  if(activeChapter!==-1){closePresentation();return;}
  const position=chapterStops.findIndex(([hash])=>hash===currentRoute());
  showChapter(Math.max(0,position));
});
